import { EmailAttachment } from './mail.types';

/**
 * Pre-encoded email branding attachments (CID Inline Images)
 * Generated from high-resolution official assets, optimized for email client delivery.
 * No external HTTP requests or runtime filesystem lookups are required.
 */

export const NAVRATRI_LOGO_BASE64 = '';

export const NAVRATRI_LOGO_ATTACHMENT: EmailAttachment = {
  filename: 'ongc-navratri-logo.png',
  content: NAVRATRI_LOGO_BASE64,
  contentType: 'image/png',
  cid: 'navratri-logo',
  encoding: 'base64',
};

export const ZAIRA_LOGO_BASE64 = '';

export const ZAIRA_LOGO_ATTACHMENT: EmailAttachment = {
  filename: 'zaira-diamond-logo.png',
  content: ZAIRA_LOGO_BASE64,
  contentType: 'image/png',
  cid: 'zaira-logo',
  encoding: 'base64',
};

export const OM_SANCTUARY_LOGO_BASE64 = '';

export const OM_SANCTUARY_LOGO_ATTACHMENT: EmailAttachment = {
  filename: 'om-sanctuary-palace-logo.png',
  content: OM_SANCTUARY_LOGO_BASE64,
  contentType: 'image/png',
  cid: 'om-sanctuary-logo',
  encoding: 'base64',
};

