/**
 * Returns all static branding attachments for inclusion in official E-Pass emails.
 */
export function getEmailBrandingAttachments(): EmailAttachment[] {
  return [
    NAVRATRI_LOGO_ATTACHMENT,
    ZAIRA_LOGO_ATTACHMENT,
    OM_SANCTUARY_LOGO_ATTACHMENT,
    LALKAAR_LOGO_ATTACHMENT,
    DIGANT_ART_LOGO_ATTACHMENT,
  ];
}
